/* Ten independent, deterministic referees review consequential changes. */
(function(root){
'use strict';
const yes=reason=>({vote:'allow',reason}), no=reason=>({vote:'block',reason}), skip=()=>({vote:'abstain',reason:'Outside this referee’s remit.'});
const person=(s,id)=>s.agents.find(a=>a.id===id);
const near=(a,b)=>Math.abs(a.x-b.x)+Math.abs(a.y-b.y)<=2;
const inWorld=(s,a)=>a&&a.alive&&Number.isInteger(a.x)&&Number.isInteger(a.y)&&a.x>=0&&a.y>=0&&a.x<s.width&&a.y<s.height;
const reviews=[
  ['Conservation',(s,p)=>{if(p.kind==='experiment'){let a=person(s,p.actor),c=p.candidate;if(!a||!c)return no('An experiment needs a living experimenter and a method.');for(const [k,n] of Object.entries(c.costs||{}))if((k==='food'||k==='water'?a[k]:a.supplies?.[k]||0)<n)return no(`Not enough ${k} exists in the experimenter’s stores.`);return yes('The experiment can spend its stated materials.')}if(p.kind==='build'&&!p.prototype){let a=person(s,p.actor),cost=p.node?.effect==='fire'?{wood:1,stone:1}:p.node?.effect==='edge'?{stone:1}:{wood:1,fibre:1};if(!a||Object.entries(cost).some(([k,n])=>(a.supplies?.[k]||0)<n))return no('The builder lacks the required materials.');return yes('Construction materials are accounted for.')}if(p.kind==='birth'){let a=person(s,p.parents?.[0]),b=person(s,p.parents?.[1]);return a&&b&&a.food>=(root.RealismRules?.birthMinFood??5)&&b.food>=(root.RealismRules?.birthMinFood??5)&&a.water>=(root.RealismRules?.birthMinWater??4)&&b.water>=(root.RealismRules?.birthMinWater??4)?yes('Parents have food and water to share.'):no('The parents cannot provision a newborn.')}return skip()}],
  ['Space',(s,p)=>{if(['experiment','build','birth','item-discovery','clan'].includes(p.kind)){let ids=p.kind==='birth'?p.parents:p.kind==='clan'?p.members:[p.actor];if(!ids?.every(id=>inWorld(s,person(s,id))))return no('A participant is outside the living world.');if(p.kind==='birth'&&!near(person(s,ids[0]),person(s,ids[1])))return no('Parents are too far apart.');return yes('Participants occupy valid places in the world.')}if(p.kind==='intervention'&&p.command.kind!=='weather'&&!(p.command.kind==='remove'&&p.command.scope==='world'))return Number.isInteger(Number(p.command.tileIndex))&&s.tiles[Number(p.command.tileIndex)]?yes('The selected place exists.'):no('The selected place does not exist.');return skip()}],
  ['Causality',(s,p)=>{if(p.kind==='experiment'){let c=p.candidate;return c?.parents?.every(id=>{let n=s.tech.nodes.find(t=>t.id===id);return n&&n.day<=s.day&&person(s,p.actor)?.knowledge.includes(id)})?yes('Earlier discoveries support this attempt.'):no('A required discovery has not been learned.')}if(p.kind==='build')return p.node?.day<=s.day&&s.tech.nodes.some(n=>n.id===p.node.id)?yes('The invention exists before construction.'):no('Construction precedes the invention.');if(p.kind==='expansion')return s.width<16&&s.explored.length>=(s.lastExpansionExplored||0)+Math.ceil(s.width*s.height*.25)?yes('Exploration has reached the expansion threshold.'):no('The edge has not been explored enough.');return skip()}],
  ['Ecology',(s,p)=>{if(p.kind==='expansion')return s.width<16&&s.height<16?yes('New land can adjoin the known map.'):no('The map has reached its supported extent.');if(p.kind==='intervention'){let c=p.command;if(c.kind==='terrain')return ['grass','forest','berry','water','rock'].includes(c.terrain)?yes('The terrain has a defined ecology.'):no('Unknown terrain cannot be created.');if(c.kind==='remove'){let spots=c.scope==='world'?s.tiles:[s.tiles[Number(c.tileIndex)]],total=spots.filter(Boolean).reduce((n,t)=>n+(t[c.category]||0)+(t.items||[]).filter(i=>i.category===c.category).reduce((m,i)=>m+i.quantity,0),0);return total>0?yes('There is something physical to remove.'):no('That resource is absent from the selected reach.')}return yes('The intervention has a physical effect in this world.')}return skip()}],
  ['Physiology',(s,p)=>{if(p.kind==='birth'){let a=person(s,p.parents?.[0]),b=person(s,p.parents?.[1]);return a?.alive&&b?.alive&&a.age>=18&&b.age>=18&&a.health>=55&&b.health>=55&&s.agents.filter(x=>x.alive).length<18?yes('Living adults can sustain a birth.'):no('Age, health, or population prevents birth.')}return skip()}],
  ['Knowledge',(s,p)=>{if(p.kind==='experiment'){let a=person(s,p.actor),c=p.candidate;return a&&c&&root.TechReferee.possibilities(a,s).some(x=>x.id===c.id)?yes('The method follows this person’s observations and knowledge.'):no('This method has not emerged from what this person knows.')}if(p.kind==='build')return person(s,p.actor)?.knowledge.includes(p.node?.id)?yes('The builder knows the invention.'):no('The builder has not learned this invention.');if(p.kind==='item-discovery')return person(s,p.actor)?.knownItems?.[p.itemId]==='tested'?yes('The object was physically tested.'):no('The object has not been tested.');return skip()}],
  ['Social',(s,p)=>{if(p.kind==='birth'){let a=person(s,p.parents?.[0]),b=person(s,p.parents?.[1]);return a&&b&&(a.likes[b.id]||0)>=(root.RealismRules?.birthBondMinimum??68)&&(b.likes[a.id]||0)>=(root.RealismRules?.birthBondMinimum??68)?yes('Both parents show a strong mutual bond.'):no('Mutual affinity is too low.')}if(p.kind==='clan'){let group=p.members?.map(id=>person(s,id));if(!group||group.length<3||group.some(a=>!a?.alive))return no('A clan needs at least three living members.');let connected=new Set([group[0].id]);let changed=true;while(changed){changed=false;for(const a of group)for(const b of group)if(connected.has(a.id)&&!connected.has(b.id)&&(a.likes[b.id]||0)>=65&&(b.likes[a.id]||0)>=65){connected.add(b.id);changed=true}}return connected.size===group.length?yes('Mutual relationships connect the whole group.'):no('The group lacks reciprocal ties.')}return skip()}],
  ['Heredity',(s,p)=>{if(p.kind!=='birth')return skip();let a=person(s,p.parents?.[0]),b=person(s,p.parents?.[1]);if(!a||!b||a.id===b.id)return no('Two distinct parents are required.');if(a.parents.includes(b.id)||b.parents.includes(a.id)||a.parents.some(id=>b.parents.includes(id)))return no('Close relatives cannot be paired.');return a.genes&&b.genes?yes('Two distinct gene pools are available for inheritance.'):no('A parent has no inherited traits.')}],
  ['Engineering',(s,p)=>{if(p.kind==='experiment'){let a=person(s,p.actor),c=p.candidate;return a&&c&&s.tiles[a.y*s.width+a.x]?.type===c.site?yes('The method is attempted in a suitable place.'):no('This method needs a different environment.')}if(p.kind==='build'){let a=person(s,p.actor),n=p.node,t=a&&s.tiles[a.y*s.width+a.x];return t&&n&&!t.structures.some(x=>x.techId===n.id)?yes('This invention can leave a new visible structure here.'):no('The structure already exists or has no site.')}return skip()}],
  ['Overseer boundary',(s,p)=>{if(p.kind!=='intervention')return skip();let c=p.command,qty=Number(c.quantity),duration=Number(c.duration);if(c.kind==='add')return String(c.name||'').trim()&&['food','water','wood','stone','fibre','hazard','mystery'].includes(c.category)&&Number.isInteger(qty)&&qty>=1&&qty<=30?yes('A bounded physical object can be introduced.'):no('The object needs a name, physical role, and quantity from 1 to 30.');if(c.kind==='remove')return ['food','water','wood','stone','fibre'].includes(c.category)&&['tile','world'].includes(c.scope)&&Number.isInteger(qty)&&qty>=1&&qty<=999?yes('A bounded physical resource can be removed.'):no('The removal amount, resource, or reach is invalid.');if(c.kind==='weather')return ['clear','rain','wind'].includes(c.weather)&&Number.isInteger(duration)&&duration>=1&&duration<=20?yes('Weather has a bounded duration.'):no('Weather or duration is invalid.');if(c.kind==='terrain')return yes('Terrain changes remain physical and observable.');return no('Direct changes to minds or unsupported world rules are forbidden.')}]
];
function ensure(s){s.council ||= {decisions:[],approved:0,blocked:0};s.council.decisions ||= [];s.council.approved ||= 0;s.council.blocked ||= 0}
function reviewEdict(s,p){const q=p.plan||{},e=q.effect||{},target=s.agents.find(a=>a.id===e.targetId),validTile=Number.isInteger(q.tileIndex)&&!!s.tiles[q.tileIndex],quantity=Number.isInteger(Number(e.quantity))&&Number(e.quantity)>=1&&Number(e.quantity)<=99999;
 const findings=[
  [!['add','remove','person'].includes(e.kind)||quantity,'The proposed quantity can be represented in world state.','The quantity cannot be represented.'],
  [validTile,'The intervention is anchored to a mapped place.','The selected place does not exist.'],
  [Number.isInteger(s.day)&&s.day>=1,'The change can be placed on the current timeline.','The world has no valid current day.'],
  [(e.kind!=='remove'||['food','water','wood','stone','fibre'].includes(e.category))&&(e.kind!=='terrain'||['grass','forest','berry','water','rock'].includes(e.terrain)),'Resources and terrain have map representations.','The material or terrain cannot be represented.'],
  [e.kind!=='person'||!!target?.alive,'The affected person is living before the event.','The affected person is not living.'],
  [!!q.perception,'Inhabitants can perceive a sensory trace without receiving the edict.','No sensory trace is available.'],
  [e.kind!=='person'||!!target,'The named person can be found in this society.','The named person does not exist.'],
  [e.kind!=='person'||!!target?.genes,'The person’s lineage record remains attached.','The person has no lineage record.'],
  [['add','remove','terrain','weather','person'].includes(e.kind),'The effect has an executable world operation.','The effect has no executable operation.'],
  [!!q.description,'The overseer instruction and its interpretation are recorded.','No overseer instruction was supplied.']
 ];return reviews.map(([name],i)=>({name,...(findings[i][0]?yes(findings[i][1]):no(findings[i][2]))}))}
function decide(s,p){ensure(s);const votes=p.kind==='edict'?reviewEdict(s,p):reviews.map(([name,fn])=>({name,...fn(s,p)}));const approved=!votes.some(v=>v.vote==='block')&&votes.filter(v=>v.vote==='allow').length>=2;const result={day:s.day,kind:p.kind,label:p.label||p.kind,approved,votes,interpretation:p.plan?.interpretation};s.council.decisions.push(result);if(s.council.decisions.length>100)s.council.decisions.shift();s.council[approved?'approved':'blocked']++;return result}
root.Council={ensure,decide,reviewers:reviews.map(([name])=>name)};
if(typeof module!=='undefined')module.exports=root.Council;
})(typeof window!=='undefined'?window:globalThis);
